    streamGroupEvents: {
        parameters: {
            query: {
                /**
                 * @description `POST /api/v1/realtime/tickets` 의 `ticket`
                 *     - 발급 뒤 30초 안 · 처음 쓰는 것
                 *     - 없거나 모양이 틀림 → `401 REALTIME_TICKET_INVALID`
                 * @example q3V9cX0bS2lQe1o7YfW8nB4tH6kR2mJ5pL0aD9sG1uE
                 */
                ticket: string;
            };
            header?: {
                /** @description 무시한다 (RB14) */
                "Last-Event-ID"?: string;
            };
            path?: never;
            cookie?: never;
        };
        requestBody?: never;
        responses: {
            /** @description 이벤트 스트림 — `Cache-Control no-cache` · `X-Accel-Buffering no` */
            200: {
                headers: {
                    "Cache-Control"?: "no-cache";
                    "X-Accel-Buffering"?: "no";
                    [name: string]: unknown;
                };
                content: {
                    /**
                     * @example id: 17
                     *     event: board.snapshot
                     *     data: {"version":17,"date":"2026-11-12","groupStatus":"IN_PROGRESS","entries":[...],"sentAt":"2026-11-12T07:30:00.910233+09:00"}
                     *
                     *     id: 18
                     *     event: member.progressed
                     *     data: {"version":18,"date":"2026-11-12","groupStatus":"IN_PROGRESS","userId":"dohyun","entries":[...],"occurredAt":"2026-11-12T07:31:02.004118+09:00"}
                     *
                     *     : ping
                     */
                    "text/event-stream": string;
                };
            };
            /**
             * @description `REALTIME_TICKET_INVALID` → 새 티켓으로 다시 연결
             *     - `ticket` 없음 · 모양 틀림 · 없는 티켓
             *     - 30초 지남 · 이미 씀
             */
            401: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    /**
                     * @example {
                     *       "code": "REALTIME_TICKET_INVALID",
                     *       "message": "실시간 연결 티켓이 없거나 만료되었습니다."
                     *     }
                     */
                    "application/json": components["schemas"]["ErrorResponse"] & {
                        /** @constant */
                        code?: "REALTIME_TICKET_INVALID";
                    };
                };
            };
            /**
             * @description `GAME_NOT_OPEN`
             *     - 티켓은 맞지만 그날 명단 · 그룹 상태(Redis)가 없음
             */
            409: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["ErrorResponse"] & {
                        /** @constant */
                        code?: "GAME_NOT_OPEN";
                    };
                };
            };
            500: components["responses"]["InternalError"];
            503: components["responses"]["Unavailable"];
        };
    };
